<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
require_once __DIR__.'/app/Services/DeveloperBackup633.php';
Auth::requireLogin();
$user=Auth::user(); $role=(string)($user['role']??'');
if(!in_array($role,['developer','admin'],true)){http_response_code(403);exit('دسترسی کافی نیست.');}
$isDev=$role==='developer'; $uid=$isDev?0:(int)$user['id'];
header('Cache-Control: no-store, private');header('X-Robots-Tag: noindex, nofollow');
$msg='';$error='';
try{
 if(isset($_GET['download'])){DeveloperBackup633::download((string)$_GET['download']);}
 if($_SERVER['REQUEST_METHOD']==='POST'){
  csrf_verify();$op=(string)($_POST['op']??'');
  if($op==='backup'){$r=DeveloperBackup633::backup();Logger::audit('backup.manual_created',['file'=>$r['name'],'actor_id'=>$user['id']]);$msg='بکاپ ایجاد شد: '.$r['name'];}
  elseif($op==='telegram'){
   $old=DeveloperBackup633::settings($uid);
   $token=trim((string)($_POST['bot_token']??''));$chat=trim((string)($_POST['chat_id']??''));
   if($chat==='' && ($old['chat']??'')!=='') $chat=(string)$old['chat'];
   DeveloperBackup633::saveSettings($token,$chat,$uid);
   Logger::audit('backup.telegram_settings_changed',['actor_id'=>$user['id']]);$msg='تنظیمات تلگرام ذخیره شد.';
  }elseif($op==='send'){
   DeveloperBackup633::sendTelegram((string)($_POST['file']??''),$uid);
   Logger::audit('backup.manual_telegram_sent',['actor_id'=>$user['id']]);$msg='بکاپ به تلگرام ارسال شد.';
  }else throw new RuntimeException('درخواست نامعتبر است.');
 }
}catch(Throwable $e){$error=$e->getMessage();}
$s=DeveloperBackup633::settings($uid);$files=DeveloperBackup633::list();
$hasToken=!empty($s['token']);$suffix=$hasToken?substr((string)$s['token'],-4):'';
$cron='cd "$HOME/public_html/soltan.toseno.ir" && /usr/local/bin/php cron_soltan_backup.php';
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>بکاپ و تلگرام | سلطان حساب</title><style>
:root{font-family:Tahoma,Arial,sans-serif;color:#16233b;background:#f3f6fb}*{box-sizing:border-box}body{margin:0;line-height:1.85;font-size:14px}a{color:#175de8}main{max-width:1080px;padding:24px;margin:auto}.top{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:0 0 24px}.top a{display:inline-block;padding:8px 13px;background:white;border:1px solid #dce3ef;border-radius:10px;text-decoration:none}h1{font-size:24px;margin:0}h2{font-size:18px;margin:0 0 12px}.muted{color:#64748b}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.card{min-width:0;background:#fff;border:1px solid #dfe6f1;border-radius:15px;padding:22px;margin-bottom:16px;box-shadow:0 1px 3px #0b2b5310}.wide{grid-column:1/-1}.hint{background:#eef4ff;padding:12px;border-radius:10px;color:#254a8a}.ok{background:#e5f8ed;color:#126437;padding:11px;border-radius:9px}.err{background:#fff0f0;color:#a12424;padding:11px;border-radius:9px}label{display:block;font-weight:600;margin:12px 0 5px}input{width:100%;border:1px solid #ccd6e7;border-radius:9px;padding:11px 12px;font:inherit;font-size:16px;min-width:0}button,.btn{background:#175de8;color:white;border:0;padding:10px 16px;font:inherit;border-radius:9px;cursor:pointer;text-decoration:none;display:inline-block}button.secondary{background:#eaf0fa;color:#184681}button:hover{filter:brightness(.96)}.status{display:inline-block;border-radius:50px;padding:2px 11px;background:#e5f8ed;color:#126437;font-weight:700}.badstatus{background:#fff1e7;color:#ab5400}.actions{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.inline{display:inline}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:520px}th,td{padding:12px;border-bottom:1px solid #e7edf5;text-align:right}td.file{direction:ltr;text-align:right;overflow-wrap:anywhere;font-size:12px}code,pre{direction:ltr;text-align:left;unicode-bidi:plaintext;background:#f2f5fa;border-radius:8px;padding:10px;display:block;overflow:auto;font-size:13px}.steps{padding-right:22px}.steps li{margin:7px 0}summary{cursor:pointer;font-weight:700}footer{color:#667085;padding:14px 0}@media(max-width:740px){main{padding:12px}.grid{grid-template-columns:1fr}.card{padding:15px}h1{font-size:20px}}
